                    lock (_gate)
                    {
                        Purge();
                        return WeakHandle.Probe(key) is WeakHandle p && _data.TryGetValue(p, out var v) ? v : throw new KeyNotFoundException(Builtins.repr(key));
                    }
                }
                set
                {
                    var probe = WeakHandle.Probe(key) ?? throw new InvalidCastException($"cannot create weak reference to '{(key == null ? "NoneType" : Builtins.PyTypeName(key.GetType()))}' object");
                    lock (_gate)
                    {
                        Purge();
                        // an equal key already there keeps its handle (and the position), as a dict keeps its first key
                        int at = _data.IndexOf(probe);
                        if (at >= 0) _data.SetAt(at, value);
                        else _data[WeakHandle.Weak(key, _onCollected)] = value;
                    }
                }
            }

            public void __delitem__(object? key)
            {
                lock (_gate) { Purge(); if (!(WeakHandle.Probe(key) is WeakHandle p && _data.Remove(p))) throw new KeyNotFoundException(Builtins.repr(key)); }
            }

            public bool __contains__(object? key)
            {
                lock (_gate) { Purge(); return WeakHandle.Probe(key) is WeakHandle p && _data.ContainsKey(p); }
            }

            public override long __len__() => Live().Count;
            public dynamic? get(object? key, object? @default = null)
            {
                lock (_gate) { Purge(); return WeakHandle.Probe(key) is WeakHandle p && _data.TryGetValue(p, out var v) ? v : @default; }
            }
            public List<object> keys() => Live().Select(x => x.Key).ToList();
            public List<object?> values() => Live().Select(x => x.Value).ToList();
            public List<(object, object?)> items() => Live();
            public List<@ref> keyrefs() => Live().Select(x => new @ref(x.Key)).ToList();

            public dynamic? pop(object? key)
            {
                lock (_gate)
                {
                    Purge();
                    if (WeakHandle.Probe(key) is WeakHandle p && _data.Remove(p, out var v)) return v;
                    throw new KeyNotFoundException(Builtins.repr(key));
                }
            }
            public dynamic? pop(object? key, object? @default)
            {
                lock (_gate) { Purge(); return WeakHandle.Probe(key) is WeakHandle p && _data.Remove(p, out var v) ? v : @default; }
            }
            public (object, object?) popitem()
            {
                lock (_gate)
                {
                    Purge();
                    while (_data.Count > 0)
                    {
                        var kv = _data.GetAt(_data.Count - 1);
                        _data.RemoveAt(_data.Count - 1);
                        if (kv.Key.Target is object k) return (k, kv.Value);
                    }
                    throw new KeyNotFoundException("'popitem(): dictionary is empty'");
                }
            }
            public dynamic? setdefault(object? key, object? @default = null)
            {
                lock (_gate)
                {
                    Purge();
                    if (WeakHandle.Probe(key) is WeakHandle p && _data.TryGetValue(p, out var v)) return v;
                }
                this[key] = @default;
                return @default;
            }
            public void clear() { lock (_gate) _data.Clear(); }
            public WeakKeyDictionary copy()
            {
                var d = new WeakKeyDictionary();
                foreach (var (k, v) in Live()) d[k] = v;
                return d;
            }
            public void update(object? dict = null)
            {
                if (dict == null) return;
                if (dict is IDictionary d) { foreach (DictionaryEntry e in d) this[e.Key] = e.Value; return; }
                if (dict is WeakKeyDictionary w) { foreach (var (k, v) in w.Live()) this[k] = v; return; }
                foreach (var pair in (IEnumerable)dict) { var t = (ITuple)pair!; this[t[0]] = t[1]; }
            }

            public IEnumerator<object?> GetEnumerator() => Live().Select(x => (object?)x.Key).GetEnumerator();
            IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
        }

        /// <summary>weakref.WeakSet: a set whose items are held weakly (an item goes when it is collected).</summary>
        internal class WeakSet : WeakCollection, ICollection<object?>
        {
            readonly OrderedDictionary<WeakHandle, bool> _data = new OrderedDictionary<WeakHandle, bool>();

            public WeakSet() { }
            public WeakSet(object? data) { if (data != null) update(data); }

            protected override void Forget(WeakHandle h) => _data.Remove(h);

            List<object> Live()
            {
                lock (_gate)
                {
                    Purge();
                    var r = new List<object>();
                    foreach (var kv in _data) if (kv.Key.Target is object x) r.Add(x);
                    return r;
                }
            }

            public void add(object? item)
            {
                var probe = WeakHandle.Probe(item) ?? throw new InvalidCastException($"cannot create weak reference to '{(item == null ? "NoneType" : Builtins.PyTypeName(item.GetType()))}' object");
                lock (_gate) { Purge(); if (!_data.ContainsKey(probe)) _data[WeakHandle.Weak(item, _onCollected)] = true; }
            }
            public void remove(object? item)
            {
                lock (_gate) { Purge(); if (!(WeakHandle.Probe(item) is WeakHandle p && _data.Remove(p))) throw new KeyNotFoundException(Builtins.repr(item)); }
            }
            public void discard(object? item) { lock (_gate) { Purge(); if (WeakHandle.Probe(item) is WeakHandle p) _data.Remove(p); } }
            public dynamic? pop()
            {
                lock (_gate)
                {
                    Purge();
                    while (_data.Count > 0)
                    {
                        var h = _data.GetAt(0).Key;
                        _data.RemoveAt(0);
                        if (h.Target is object x) return x;
                    }
                    throw new KeyNotFoundException("'pop from empty WeakSet'");
                }
            }
            public bool __contains__(object? item) { lock (_gate) { Purge(); return WeakHandle.Probe(item) is WeakHandle p && _data.ContainsKey(p); } }
            public override long __len__() => Live().Count;
            public void clear() { lock (_gate) _data.Clear(); }
            public WeakSet copy() => new WeakSet(Live());
            public void update(object? other) { foreach (var x in (IEnumerable)other!) add(x); }

            public WeakSet union(object? other) { var r = copy(); r.update(other); return r; }
            public WeakSet intersection(object? other) { var o = new WeakSet(other); return new WeakSet(Live().Where(o.__contains__)); }
            public WeakSet difference(object? other) { var o = new WeakSet(other); return new WeakSet(Live().Where(x => !o.__contains__(x))); }
            public WeakSet symmetric_difference(object? other)
            {
                var o = new WeakSet(other);
                return new WeakSet(Live().Where(x => !o.__contains__(x)).Concat(o.Live().Where(x => !__contains__(x))));
            }
            public bool issubset(object? other) { var o = new WeakSet(other); return Live().All(o.__contains__); }
            public bool issuperset(object? other) => new WeakSet(other).Live().All(__contains__);
            public bool isdisjoint(object? other) => !new WeakSet(other).Live().Any(__contains__);
            public static WeakSet operator |(WeakSet a, WeakSet b) => a.union(b);
            public static WeakSet operator &(WeakSet a, WeakSet b) => a.intersection(b);
            public static WeakSet operator -(WeakSet a, WeakSet b) => a.difference(b);
            public static WeakSet operator ^(WeakSet a, WeakSet b) => a.symmetric_difference(b);
            public override bool Equals(object? obj) => obj is WeakSet o && o.__len__() == __len__() && issubset(o);
            public override int GetHashCode() => throw new InvalidCastException("unhashable type: 'WeakSet'");

            void ICollection<object?>.Add(object? item) => add(item);
            public bool Contains(object? item) => __contains__(item);
            public bool Remove(object? item) { lock (_gate) { Purge(); return WeakHandle.Probe(item) is WeakHandle p && _data.Remove(p); } }
            void ICollection<object?>.Clear() => clear();
            public void CopyTo(object?[] array, int index) { foreach (var x in Live()) array[index++] = x; }
            public bool IsReadOnly => false;
            public IEnumerator<object?> GetEnumerator() => Live().Select(x => (object?)x).GetEnumerator();
            IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
            public override string __repr__() => "{" + string.Join(", ", Live().Select(x => $"<weakref at {PyWait.Address(x)}; {Describe(x)}>")) + "}";
        }
    }

    /// <summary>_weakrefset: where WeakSet lives in CPython.</summary>
    internal static class _weakrefset
    {
        internal sealed class WeakSet : weakref.WeakSet
        {
            public WeakSet() { }
            public WeakSet(object? data) : base(data) { }
        }
    }

